// Validate the payload shape (auth already checked by the Authorized? node).
const req = $input.first().json;
const body = req.body || {};

const errors = [];
if (!body.author_id) errors.push('author_id is required');
if (!body.author_name) errors.push('author_name is required');

let books = body.books;
if (typeof books === 'string') {
  try { books = JSON.parse(books); } catch (e) { errors.push('books is not valid JSON: ' + e.message); }
}
if (!Array.isArray(books)) {
  if (!errors.some((x) => x.startsWith('books'))) errors.push('books must be a list');
  books = [];
}

return [{ json: {
  valid: errors.length === 0,
  errors,
  author_id: String(body.author_id || ''),
  author_name: String(body.author_name || ''),
  author_email: String(body.author_email || ''),
  city: String(body.city || ''),
  books,
} }];

// Compute royalty facts (badges, totals, next payout) + build the AI prompt
// and a deterministic fallback email so an AI outage never breaks the flow.
const inp = $input.first().json;
const today = new Date();

const INR = (n) => '\u20B9' + Number(n || 0).toLocaleString('en-IN');
const DATE = (d) => d ? new Date(d).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' }) : null;
const DAY = 86400000;

const books = (inp.books || []).map((b) => ({
  title: String(b.title || 'Untitled'),
  status: String(b.status || ''),
  publication_date: b.publication_date || null,
  copies_sold: Number(b.copies_sold || 0),
  royalty_earned: Number(b.royalty_earned || 0),
  royalty_paid: Number(b.royalty_paid || 0),
  royalty_pending: Number(b.royalty_pending || 0),
  last_payout_date: b.last_payout_date || null,
}));

// Royalty status badge, mirroring the dashboard rule (90-day overdue window)
for (const b of books) {
  const published = b.status.startsWith('Published');
  if (!published) { b.badge = 'NA'; continue; }
  if (b.royalty_pending <= 0) { b.badge = 'GREEN'; continue; }
  const anchor = b.last_payout_date || b.publication_date;
  const overdue = anchor ? (today - new Date(anchor)) > 90 * DAY : false;
  b.badge = overdue ? 'RED' : 'YELLOW';
}

const published = books.filter((b) => b.status.startsWith('Published'));
const inProduction = books.filter((b) => !b.status.startsWith('Published'));
const totals = {
  earned: published.reduce((s, b) => s + b.royalty_earned, 0),
  paid: published.reduce((s, b) => s + b.royalty_paid, 0),
  pending: published.reduce((s, b) => s + b.royalty_pending, 0),
};
const neverPaid = published.some((b) => b.royalty_pending > 0 && !b.last_payout_date);

// Next payout from the KB: quarterly cycle (Mar 31 / Jun 30 / Sep 30 / Dec 31), paid within 45 days.
const y = today.getFullYear();
const qEnds = [new Date(y - 1, 11, 31), new Date(y, 2, 31), new Date(y, 5, 30), new Date(y, 8, 30), new Date(y, 11, 31)];
let lastQ = qEnds[0];
for (const q of qEnds) if (q <= today) lastQ = q;
const windowEnd = new Date(lastQ.getTime() + 45 * DAY);
const nextQ = qEnds.find((q) => q > today) || new Date(y + 1, 2, 31);
const nextPayout = today <= windowEnd ? windowEnd : new Date(nextQ.getTime() + 45 * DAY);
const nextPayoutStr = DATE(nextPayout);
const rollover = totals.pending > 0 && totals.pending < 1000;

// Idempotency: ignore repeat triggers for the same author within 60 seconds.
const sd = $getWorkflowStaticData('global');
sd.lastTrigger = sd.lastTrigger || {};
const prev = Number(sd.lastTrigger[inp.author_id] || 0);
const duplicate = Date.now() - prev < 60000;
if (!duplicate) sd.lastTrigger[inp.author_id] = Date.now();

// ---- Facts block (the only numbers the AI may use) ----
const lines = [];
lines.push(`Author: ${inp.author_name}${inp.city ? ' (' + inp.city + ')' : ''}`);
lines.push(`Date of this summary: ${DATE(today)}`);
lines.push('');
lines.push('PUBLISHED BOOKS:');
if (published.length === 0) lines.push('- none published yet');
for (const b of published) {
  lines.push(`- "${b.title}": ${b.copies_sold} copies sold; earned ${INR(b.royalty_earned)}; paid ${INR(b.royalty_paid)}; pending ${INR(b.royalty_pending)}; last payout ${DATE(b.last_payout_date) || 'none yet'}; payout status ${b.badge}`);
}
if (inProduction.length > 0) {
  lines.push('');
  lines.push('BOOKS IN PRODUCTION (no sales or royalties yet):');
  for (const b of inProduction) lines.push(`- "${b.title}": current stage ${b.status}`);
}
lines.push('');
lines.push(`TOTALS: earned ${INR(totals.earned)}; paid ${INR(totals.paid)}; pending ${INR(totals.pending)}`);
if (totals.pending > 0) {
  lines.push(`NEXT PAYOUT: pending amounts are expected by ${nextPayoutStr} (quarterly cycle, paid within 45 days of quarter end).`);
  if (rollover) lines.push('NOTE: the pending amount is below the \u20B91,000 minimum payout, so it rolls over to the next quarter.');
  if (neverPaid) lines.push('NOTE: this author has earned royalties but has never received a payout yet; acknowledge this plainly.');
} else {
  lines.push('ALL ROYALTIES ARE FULLY PAID UP.');
}
const factsBlock = lines.join('\n');

const systemPrompt = [
  'You write royalty summary emails from the BookLeaf author support team. A human admin reviews the email before it is sent.',
  '',
  'Writing rules:',
  "1. Open with \"Hi <author's first name>,\" then one warm sentence introducing this as their royalty summary.",
  '2. Summarise each published book with its exact sales and royalty figures from AUTHOR FACTS. Never invent amounts, dates or names. If a fact is missing, leave it out.',
  '3. Give a clear breakdown: total earned, total paid, total pending.',
  '4. If there is a pending amount, state the exact expected payout date given in AUTHOR FACTS and briefly explain the quarterly cycle with its 45-day payment window. If a note says the author has never been paid, acknowledge it honestly \u2014 no corporate deflection.',
  '5. If everything is paid up, say so with a positive acknowledgement.',
  '6. If any books are in production, add a brief, encouraging status update for them.',
  '7. Plain text only: no markdown, no bullet symbols, no placeholders. Keep it under 250 words, in short paragraphs.',
  '8. Finish with exactly:\nWarm regards,\nBookLeaf Author Support',
  '',
  'BOOKLEAF KNOWLEDGE BASE (only source of policy facts):',
  'ABOUT BOOKLEAF',
  '- Self-publishing company operating in India and the US.',
  '- BookLeaf handles cover design, typesetting, ISBN assignment, printing, distribution and royalty management.',
  '',
  'TONE RULES',
  '- Always empathetic and professional. Authors are partners, not customers to be managed.',
  '- Be specific: use actual numbers, dates and statuses instead of vague reassurance.',
  '- If royalties are delayed and it is BookLeaf\u2019s fault, own it directly.',
  '- Always end with a clear next step for the author and/or BookLeaf.',
  '',
  'ROYALTY & PAYMENTS',
  '- Split: 80/20 of net profit per book; the author receives 80%.',
  '- Royalties are calculated quarterly (quarters end Mar 31, Jun 30, Sep 30, Dec 31) and paid within 45 days of quarter end.',
  '- Minimum payout is \u20B91,000. Smaller balances roll over to the next quarter.',
  '- Paid by bank transfer to the account linked in the author dashboard; ask the author to confirm their bank details are linked if a payout is due.',
].join('\n');

const userPrompt = `AUTHOR FACTS:\n${factsBlock}\n\nWrite the royalty summary email to the author now.`;

// Deterministic fallback email (used when the AI call fails or returns nothing)
const first = (inp.author_name || 'there').split(' ')[0];
const fb = [];
fb.push(`Hi ${first},`);
fb.push('');
fb.push('Here is your latest royalty summary from BookLeaf.');
fb.push('');
for (const b of published) {
  fb.push(`${b.title}: ${b.copies_sold} copies sold, ${INR(b.royalty_earned)} earned, ${INR(b.royalty_paid)} paid, ${INR(b.royalty_pending)} pending (last payout: ${DATE(b.last_payout_date) || 'none yet'}).`);
}
if (published.length > 0) fb.push('');
fb.push(`Across all your books you have earned ${INR(totals.earned)}, of which ${INR(totals.paid)} has been paid and ${INR(totals.pending)} is pending.`);
if (totals.pending > 0) {
  fb.push(`Your pending amount is expected by ${nextPayoutStr}, in line with our quarterly cycle (royalties are paid within 45 days of each quarter end). Please make sure your bank details are linked in your dashboard.`);
  if (rollover) fb.push('As the pending amount is below the \u20B91,000 minimum payout, it will roll over to the next quarter.');
} else {
  fb.push('All your royalties are fully paid up \u2014 thank you for publishing with BookLeaf!');
}
for (const b of inProduction) {
  fb.push(`Your book "${b.title}" is currently at the ${b.status.replace('In Production - ', '')} stage. We will keep you posted as it moves forward.`);
}
fb.push('');
fb.push('Warm regards,');
fb.push('BookLeaf Author Support');

const monthYear = today.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });

return [{ json: {
  author_id: inp.author_id,
  author_name: inp.author_name,
  author_email: inp.author_email,
  duplicate,
  email_subject: `Your BookLeaf royalty summary \u2014 ${monthYear}`,
  facts: factsBlock,
  fallback_email: fb.join('\n'),
  gemini_request: {
    contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
    systemInstruction: { parts: [{ text: systemPrompt }] },
    generationConfig: { temperature: 0.3, maxOutputTokens: 1024 },
  },
} }];

// Extract the AI email; fall back to the deterministic template if the
// response is empty or malformed.
const resp = $input.first().json;
const f = $('Royalty Facts & Prompt').first().json;

let text = '';
try {
  text = (resp.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('').trim();
} catch (e) { text = ''; }

const usedAI = text.length >= 40;
return [{ json: {
  status: 'Success',
  author_id: f.author_id,
  author_name: f.author_name,
  author_email: f.author_email,
  email_subject: f.email_subject,
  email_body: usedAI ? text : f.fallback_email,
  source: usedAI ? 'AI' : 'FALLBACK',
  model: usedAI ? (resp.modelVersion || 'gemini') : null,
  note: usedAI ? undefined : 'AI returned an empty or malformed response; deterministic fallback used.',
  generated_at: new Date().toISOString(),
} }];

// AI call failed (network / quota / 4xx-5xx): never break silently.
// Serve the deterministic fallback email and say why.
const f = $('Royalty Facts & Prompt').first().json;
const err = $input.first().json?.error;
const reason = (err && (err.message || err.description)) || 'AI API call failed';

return [{ json: {
  status: 'Success',
  author_id: f.author_id,
  author_name: f.author_name,
  author_email: f.author_email,
  email_subject: f.email_subject,
  email_body: f.fallback_email,
  source: 'FALLBACK',
  model: null,
  note: 'AI unavailable: ' + String(reason).slice(0, 300),
  generated_at: new Date().toISOString(),
} }];
